(()=>{'use strict';const form=document.getElementById('business-login'),status=document.getElementById('login-status'),parents=['https://mowmatter.com','https://www.mowmatter.com'];form.querySelector('[role=status]').insertAdjacentHTML('beforebegin',MowNotice.markup('business'));{const params=new URLSearchParams(location.search);if(params.get('terms')==='accepted'){let from;try{from=new URL(document.referrer).origin}catch{}if(parents.includes(from))form.elements.account_terms.checked=true;params.delete('terms');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash)}}let marketingTouched=false;form.elements.launch_updates.addEventListener('change',()=>{marketingTouched=true});let parentOrigin;try{const origin=new URL(document.referrer).origin;if(parents.includes(origin))parentOrigin=origin}catch{}const embedded=window.parent!==window&&!!parentOrigin;function notify(data){if(embedded)window.parent.postMessage(data,parentOrigin)}function enterOffice(){if(embedded)notify({type:'mm-business-signed-in'});else location.assign('/index.html')}function proceed(){if(MM.session?.user?.user_metadata?.terms_version){enterOffice();return}const gate=document.createElement('form');gate.id='terms-gate';gate.innerHTML='<h2 class="gate-title">One last step</h2><p class="help">Agree to the Platform Terms to open your business workspace.</p>'+MowNotice.markup('business')+'<p role="status" aria-live="polite"></p><button class="button primary" type="submit">Agree and continue</button>';for(const el of [...document.querySelector('main').children])if(!el.matches('.mm-brand'))el.hidden=true;document.querySelector('main').append(gate);const note=gate.querySelector('[role=status]');gate.addEventListener('submit',async event=>{event.preventDefault();const b=gate.querySelector('button');b.disabled=true;try{await MM.acceptTerms(MowNotice.validate(gate,'business'));enterOffice()}catch(error){note.textContent=error.message;b.disabled=false}});gate.elements.account_terms.focus();resize()}function resize(){notify({type:'mm-business-login-height',height:Math.ceil(document.querySelector("main").getBoundingClientRect().height)})}async function run(task){const buttons=[...document.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);status.textContent='Working…';try{await task()}catch(error){status.textContent=error.message||'Unable to sign in. Please try again.'}finally{buttons.forEach(b=>b.disabled=false);resize()}}form.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(form),signup=event.submitter?.value==='signup';void run(async()=>{if(signup){await MM.signUp(values.get('email'),values.get('password'),form.elements.launch_updates.checked,MowNotice.validate(form,'business'));status.textContent='Check your email to confirm your account, then return to sign in.'}else{await MM.signIn(values.get('email'),values.get('password'));form.elements.password.value='';if(marketingTouched)await MM.saveLaunchUpdates(form.elements.launch_updates.checked);status.textContent='Signed in. Opening your business workspace…';proceed()}})});for(const [id,method]of [['forgot','resetPassword'],['resend','resend']])document.getElementById(id).addEventListener('click',()=>{const email=form.elements.email;if(!email.checkValidity()||!email.value){email.reportValidity();email.focus();status.textContent='Enter your account email above first.';resize();return}void run(async()=>{await MM[method](email.value);status.textContent='If eligible, an email has been requested. Check your inbox.'})});void MM.ready.then(async()=>{if(typeof MM.launchUpdatesChoice==='boolean')form.elements.launch_updates.checked=MM.launchUpdatesChoice;if(MM.session&&!MM.recovery){if(typeof MM.launchUpdatesChoice==='boolean'){const finish=async()=>{await MM.saveLaunchUpdates(form.elements.launch_updates.checked);proceed()};await run(finish);if(typeof MM.launchUpdatesChoice==='boolean'){const retry=document.createElement('button');retry.type='button';retry.className='button primary';retry.textContent='Save update preference and continue';retry.onclick=()=>run(finish);form.after(retry);}}else proceed();return}MM.mountGoogleLogin(form);if(!embedded)for(const provider of ['google','facebook']){const button=document.querySelector('[data-'+provider+'-login]');if(button)button.onclick=async()=>{button.disabled=true;button.setAttribute('aria-busy','true');try{const acceptance=form.elements.account_terms.checked?MowNotice.validate(form,'business'):undefined;await MM.socialSignIn(provider,form.elements.launch_updates.checked,acceptance)}catch(error){status.textContent=error.message;button.disabled=false;button.removeAttribute('aria-busy')}}}if(embedded)for(const provider of ['google','facebook']){const button=document.querySelector('[data-'+provider+'-login]');if(button)button.onclick=()=>{try{MowNotice.validate(form,'business');notify({type:'mm-business-login-provider',provider,launchUpdates:form.elements.launch_updates.checked,termsAccepted:true})}catch(error){status.textContent=error.message;resize()}}}resize()});new MutationObserver(()=>{if(!status.textContent)return;const box=status.getBoundingClientRect();if(box.top<0||box.bottom>innerHeight)status.scrollIntoView({block:'center',behavior:'smooth'})}).observe(status,{childList:true,characterData:true,subtree:true});if(typeof ResizeObserver!=='undefined')new ResizeObserver(resize).observe(document.querySelector("main"));})();
